def f(g):
    h,w=len(g),len(g[0])
    for p in range(1,w+1):
        ok=True
        for i in range(h):
            for j in range(w):
                if j+p<w and g[i][j]!=g[i][j+p]: ok=False;break
            if not ok: break
        if ok: return [[g[i][j%p] for j in range(2*w)] for i in range(h)]
